export default function handler(req, res) {
  if (!checkAuth(req)) {
    return res.status(401).send("401 Unauthorized — pasa ?key=televisor2024\n");
  }

  const lines = [
    '#EXTM3U x-tvg-url=""',
    '# Televisor Películas VOD — GoldTV Premium',
    '',
  ];

  for (const [name, group, logo, url] of VOD) {
    lines.push(`#EXTINF:-1 tvg-name="${name}" tvg-logo="${logo}" group-title="${group}",${name}`);
    lines.push(url);
  }

  res.setHeader("Content-Type", "application/x-mpegurl; charset=utf-8");
  res.setHeader("Cache-Control", "public, max-age=3600");
  res.status(200).send(lines.join("\n"));
}
